// Isolation test (OS-12) — construct Diagnostic with its declared inputs and nothing else, then exercise
// every public operation. (Generated by new-object.py, rewritten for strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import { asProjection, isUnknown, noSubject, type RecordHeight } from "../src/kernel/index.js";
import type { Unit } from "../src/catalog/index.js";
import { LineageReader } from "../src/facts/index.js";
import { RevisionLog, Samples } from "../src/condition/index.js";
import { ObservationLedger, score, type Score } from "../src/observation/index.js";
import { InvalidationLedger, InvalidationScope } from "../src/lineage/index.js";
import { Dispersion, Location } from "../src/statistics/index.js";
import { Bar, PopulationPartition, type SeparationRule } from "../src/calibration/index.js";
import { Diagnostic } from "../src/diagnostic/index.js";
import { inMemoryRecord } from "./catalog/in-memory-record.js";
import { factWorld } from "./support/fact-world.js";

const u = "u1" as Unit;
const v = "u2" as Unit;
/** Separates whenever asked: midway between the lowest accepted and highest passed-over score. Test-only. */
const separating: SeparationRule = { separate: (a, p) => ({ kind: "separated", theta: (Math.min(...a) + Math.max(...p)) / 2 }) };

/** v: 0.75 committed, 0.25 passed over (θ 0.5). u: three members, q 0.6, 0.7, 0.8, still open. */
function world() {
  const record = inMemoryRecord();
  const lineage = new LineageReader({ record });
  const invalidations = new InvalidationLedger({ record, scopes: new InvalidationScope({ lineage }), renderer: { present: () => undefined } });
  const w = factWorld({ currencies: ["c0"], invalidations, record });
  const c0 = w.order.least();
  const observations = new ObservationLedger({ record, components: ["q"] });
  const drawn = (unit: Unit, n: number, condition: string) => {
    const k = w.drawAt(unit, c0, condition);
    observations.observe(k, { q: { value: score(n) as Score, author: "ENGINE" } }, "ENGINE", record.noise());
    return k;
  };
  w.commitments.commit(drawn(v, 0.75, "x"), "HUMAN");
  drawn(v, 0.25, "x");
  for (const n of [0.6, 0.7, 0.8]) drawn(u, n, "y");
  const samples = new Samples({ candidates: w.candidates, draws: w.draws, revisions: new RevisionLog({ record }), lineage });
  const partition = new PopulationPartition({ lineage, samples, draws: w.draws, declarations: w.declarations, invalidations, observations });
  const h: RecordHeight = record.noise();
  const parts: ConstructorParameters<typeof Diagnostic>[0] = {
    samples,
    dispersion: new Dispersion({ samples, observations }),
    location: new Location({ samples, observations }),
    observations,
    bar: new Bar({ populations: partition, separation: separating }),
    declarations: w.declarations,
  };
  return { c0, h, parts };
}

describe("Diagnostic in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    const { parts } = world();
    for (const missing of Object.keys(parts)) expect(() => new Diagnostic({ ...parts, [missing]: undefined } as never), missing).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    const { parts } = world();
    for (const slot of Object.keys(parts)) expect(() => new Diagnostic({ ...parts, [slot]: {} } as never), slot).toThrow();
  });

  it("of answers, and differently when samples differs", () => {
    const { c0, h, parts } = world();
    const base = new Diagnostic(parts).of(u, c0, "q").compute(h);
    expect(isUnknown(base)).toBe(false);
    expect(new Diagnostic({ ...parts, samples: { samplesFor: () => [] } }).of(u, c0, "q").compute(h)).not.toEqual(base);
  });

  it("of answers differently when dispersion differs", () => {
    const { c0, h, parts } = world();
    const dispersion = { of: () => asProjection("Dispersion", () => 0.5) };
    expect(new Diagnostic({ ...parts, dispersion }).of(u, c0, "q").compute(h)).not.toEqual(new Diagnostic(parts).of(u, c0, "q").compute(h));
  });

  it("of answers differently when location differs", () => {
    const { c0, h, parts } = world();
    const location = { of: () => asProjection("Location", () => 0.1) };
    expect(new Diagnostic({ ...parts, location }).of(u, c0, "q").compute(h)).not.toEqual(new Diagnostic(parts).of(u, c0, "q").compute(h));
  });

  it("of answers differently when observations differs", () => {
    const { c0, h, parts } = world();
    expect(new Diagnostic({ ...parts, observations: { observationOf: () => noSubject() } }).of(u, c0, "q").compute(h)).not.toEqual(new Diagnostic(parts).of(u, c0, "q").compute(h));
  });

  it("of answers differently when bar differs", () => {
    const { c0, h, parts } = world();
    const bar = { of: () => asProjection("Bar", () => ({ kind: "no-bar" as const, cause: "c", discharge: "d", acceptedCount: 0, passedOverCount: 0, excludedAccepted: 0, excludedPassedOver: 0 })) };
    expect(new Diagnostic({ ...parts, bar }).of(u, c0, "q").compute(h)).not.toEqual(new Diagnostic(parts).of(u, c0, "q").compute(h));
  });

  it("of answers differently when declarations differs", () => {
    const { c0, h, parts } = world();
    expect(new Diagnostic({ ...parts, declarations: { declarationAt: () => noSubject() } }).of(u, c0, "q").compute(h)).not.toEqual(new Diagnostic(parts).of(u, c0, "q").compute(h));
  });
});
